<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_homepage_groups() { if ( ! function_exists( 'groups_get_groups' ) ) { return array(); } $sort = sd_homepage_get( 'sd_home_groups_sort' ); $result = groups_get_groups( array( 'per_page' => absint( sd_homepage_get( 'sd_home_groups_limit' ) ), 'page' => 1, 'show_hidden' => false, 'type' => in_array( $sort, array( 'active', 'newest', 'popular' ), true ) ? $sort : 'active' ) ); return ! empty( $result['groups'] ) ? $result['groups'] : array(); }
function sd_homepage_members() { if ( ! class_exists( 'BP_Core_User' ) ) { return array(); } $type = sd_homepage_get( 'sd_home_people_sort' ); $result = BP_Core_User::get( array( 'type' => in_array( $type, array( 'active', 'newest', 'random' ), true ) ? $type : 'active', 'per_page' => absint( sd_homepage_get( 'sd_home_people_limit' ) ), 'page' => 1 ) ); return ! empty( $result['users'] ) ? $result['users'] : array(); }
function sd_homepage_interests() { $terms = get_terms( array( 'taxonomy' => array( 'post_tag', 'category' ), 'hide_empty' => true, 'number' => absint( sd_homepage_get( 'sd_home_interests_limit' ) ) ) ); return is_wp_error( $terms ) ? array() : $terms; }
function sd_homepage_activities() { if ( ! function_exists( 'bp_activity_get' ) ) { return array(); } $result = bp_activity_get( array( 'per_page' => absint( sd_homepage_get( 'sd_home_discussions_limit' ) ), 'page' => 1, 'scope' => 'public', 'display_comments' => false, 'show_hidden' => false ) ); return ! empty( $result['activities'] ) ? $result['activities'] : array(); }
function sd_homepage_posts() { return new WP_Query( array( 'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => absint( sd_homepage_get( 'sd_home_articles_limit' ) ), 'ignore_sticky_posts' => true, 'no_found_rows' => true ) ); }
